/*
 * disk_$diskless_init - wire and initialise the disk code on a really
 * diskless node, once
 *
 * Original address: 0x00E6B6DC (was FUN_00e6b6dc; module-local, the first
 * routine of the `I E6B6DC DISK_ size = 1AF0` code segment, which the SAU2
 * map gives no symbol of its own)
 * Size: 94 bytes (0x00E6B6DC .. 0x00E6B739), constants to 0x00E6B74B
 * Generated by: Claude Opus 5.5
 *
 * Caller: DISK_$PV_MOUNT_INTERNAL (0x00E6C31C), for every mount type.
 *
 * A node that booted really diskless never wired the disk code: the first
 * physical-volume mount wires the OS_DISK_PROC..OS_DISK_PROC_END code range
 * and the OS_DISK_DATA..OS_DISK_DATA_END data range, initialises DBUF and
 * DISK, and clears the flag.
 *
 * Frame (link.w A6,-0x90): (-0x88) MST_$WIRE_AREA's 32-longword page list,
 * (-0x8E) its page count word - shared by both calls.
 *
 * Blocks:
 *   0x00E6B6E0-0x00E6B6E6  NETWORK_$REALLY_DISKLESS >= 0: return
 *   0x00E6B6E8-0x00E6B702  MST_$WIRE_AREA(&OS_DISK_PROC, &OS_DISK_PROC_END,
 *                          pages, &0x20, &count)
 *   0x00E6B706-0x00E6B720  MST_$WIRE_AREA(&OS_DISK_DATA, &OS_DISK_DATA_END,
 *                          pages, &0x20, &count)
 *   0x00E6B724-0x00E6B730  DBUF_$INIT; DISK_$INIT;
 *                          NETWORK_$REALLY_DISKLESS = FALSE
 *
 * Quirk reproduced: the wired page lists are discarded on return.
 */

#include "disk/disk_internal.h"
#include "mst/mst.h"
#include "network/network.h"
#include "dbuf/dbuf.h"

/*
 * The constants the two MST_$WIRE_AREA calls pass by reference (`pea
 * (d,PC)`), with their image bytes.  The four VAs are the SAU2 link map's
 * OS_DISK_PROC (E3824C), OS_DISK_PROC_END (E3E746), OS_DISK_DATA (E784D0)
 * and OS_DISK_DATA_END (E7B044); no linked object stands for them yet, so
 * they keep the image values (as PEB_$LOAD_WCS's ranges do).
 */
static const uint16_t disk_$wire_max_pages = 0x0020;    /* 0x00E6B73A: 00 20 */
static const uint32_t disk_$wire_proc_end  = 0x00E3E746u; /* 0x00E6B73C: 00 e3 e7 46 */
static const uint32_t disk_$wire_data_start = 0x00E784D0u; /* 0x00E6B740: 00 e7 84 d0 */
static const uint32_t disk_$wire_data_end  = 0x00E7B044u; /* 0x00E6B744: 00 e7 b0 44 */
static const uint32_t disk_$wire_proc_start = 0x00E3824Cu; /* 0x00E6B748: 00 e3 82 4c */

void disk_$diskless_init(void)
{
    uint32_t pages[32];                 /* (-0x88,A6) */
    uint16_t count;                     /* (-0x8E,A6) */

    /* 0x00E6B6E0-0x00E6B6E6 */
    if (NETWORK_$REALLY_DISKLESS < 0) {
        /* 0x00E6B6E8-0x00E6B702 */
        MST_$WIRE_AREA(&disk_$wire_proc_start, &disk_$wire_proc_end, pages,
                       &disk_$wire_max_pages, &count);
        /* 0x00E6B706-0x00E6B720 */
        MST_$WIRE_AREA(&disk_$wire_data_start, &disk_$wire_data_end, pages,
                       &disk_$wire_max_pages, &count);
        /* 0x00E6B724-0x00E6B730 */
        DBUF_$INIT();
        DISK_$INIT();
        NETWORK_$REALLY_DISKLESS = 0;
    }
}
